// ================================================================
// ImportGame
// Runs the "Add a Game" window: showing the right boxes per platform,
// filling in Launch IDs from a typed name or from your installed games,
// and handing the finished game to the app.
// ================================================================
class ImportGame {
    // Example text and help shown under Launch ID for each platform
    static LAUNCH_HINTS = {
        'Steam': { placeholder: '1245620', hint: 'The number in the game\'s store link: store.steampowered.com/app/<b>1245620</b>/…' },
        'Epic Games': { placeholder: 'namespace:catalogItemId:appName', hint: 'Filled in when you pick a game from the list above.' },
        'Battle.net': { placeholder: 'Pro', hint: 'A short product code, e.g. <b>Pro</b> for Overwatch 2 — filled in from the game name.' }
    };

    // Names used to remember each installed-games list in the browser
    static STEAM_STORAGE_KEY = 'gamecentral-steam-installed';
    static EPIC_STORAGE_KEY = 'gamecentral-epic-games';
    static BATTLENET_STORAGE_KEY = 'gamecentral-battlenet-installed';

    // Shows a message under a field. Error messages (isError = true) are shown in red.
    static setStatus(el, text, isError) {
        el.textContent = text;
        el.classList.toggle('error', !!isError);
    }

    constructor(options) {
        this.onGameImported = options.onGameImported; // the app saves + shows the new game

        // ---- Main form ----
        this.backdrop = document.getElementById('add-game-backdrop');
        this.form = document.getElementById('add-game-form');
        this.nameInput = document.getElementById('new-game-name');
        this.platformSelect = document.getElementById('new-game-platform');
        this.playStyleSelect = document.getElementById('new-game-play-style');
        this.launchIdInput = document.getElementById('new-game-launch-id');
        this.launchIdHint = document.getElementById('launch-id-hint');

        // ---- Steam ----
        this.steamInstalled = ImportGame.loadList(ImportGame.STEAM_STORAGE_KEY); // [[appId, name], ...]
        this.steamImportRow = document.getElementById('steam-import-row');
        this.steamFilesInput = document.getElementById('steam-files-input');
        this.steamGameSelect = document.getElementById('steam-game-select');
        this.steamImportStatus = document.getElementById('steam-import-status');
        this.steamLookupStatus = document.getElementById('steam-lookup-status');
        this.steamAutofillRow = document.getElementById('steam-autofill-row');
        this.steamUrlInput = document.getElementById('steam-url-input');
        this.steamAutofillStatus = document.getElementById('steam-autofill-status');
        this.steamNameIndex = null; // fast name lookup, built on first search
        this.steamNormNames = null;
        this.steamLookupTimer = null;

        // ---- Epic ----
        this.epicGames = ImportGame.loadList(ImportGame.EPIC_STORAGE_KEY); // [[launchId, name], ...]
        this.epicImportRow = document.getElementById('epic-import-row');
        this.epicFolderInput = document.getElementById('epic-folder-input');
        this.epicGameSelect = document.getElementById('epic-game-select');
        this.epicImportStatus = document.getElementById('epic-import-status');
        this.epicLookupStatus = document.getElementById('epic-lookup-status');
        this.epicLookupTimer = null;

        // ---- Battle.net ----
        this.battleInstalled = ImportGame.loadList(ImportGame.BATTLENET_STORAGE_KEY); // [[code, name], ...]
        this.battleImportRow = document.getElementById('battle-import-row');
        this.battleFilesInput = document.getElementById('battle-files-input');
        this.battleGameSelect = document.getElementById('battle-game-select');
        this.battleImportStatus = document.getElementById('battle-import-status');
        this.battleLookupStatus = document.getElementById('battle-lookup-status');
        this.battleLookupTimer = null;

        this.renderSteamSelect();
        this.renderEpicSelect();
        this.renderBattleSelect();
        this.bindEvents();
        this.updateLaunchField();
    }

    // ---- Buttons and inputs ----
    bindEvents() {
        // Typing a name tries to fill in the Launch ID
        this.nameInput.addEventListener('input', () => {
            this.maybeAutoLookupSteam();
            this.maybeAutoLookupEpic();
            this.maybeAutoLookupBattle();
        });
        this.platformSelect.addEventListener('change', () => this.updateLaunchField());

        // Steam
        this.steamUrlInput.addEventListener('input', () => this.handleSteamUrlInput());
        document.getElementById('steam-search-button').addEventListener('click', () => {
            const name = this.nameInput.value.trim();
            window.open(name ? 'https://store.steampowered.com/search/?term=' + encodeURIComponent(name)
                             : 'https://store.steampowered.com/', '_blank', 'noopener');
        });
        document.getElementById('steam-files-button').addEventListener('click', () => this.steamFilesInput.click());
        this.steamFilesInput.addEventListener('change', () => this.importSteamManifests());
        this.steamGameSelect.addEventListener('change', () => this.pickSteamGame());
        document.getElementById('steam-clear-button').addEventListener('click', () => this.clearSteamInstalled());

        // Epic
        document.getElementById('epic-folder-button').addEventListener('click', () => this.epicFolderInput.click());
        this.epicFolderInput.addEventListener('change', () => this.importEpicManifests(this.epicFolderInput));
        this.epicGameSelect.addEventListener('change', () => this.pickEpicGame());
        document.getElementById('epic-clear-button').addEventListener('click', () => this.clearEpicGames());

        // Battle.net
        document.getElementById('battle-files-button').addEventListener('click', () => this.battleFilesInput.click());
        this.battleFilesInput.addEventListener('change', () => this.importBattlenetDb());
        this.battleGameSelect.addEventListener('change', () => this.pickBattleGame());
        document.getElementById('battle-clear-button').addEventListener('click', () => this.clearBattleInstalled());

        // Opening and closing the window
        document.getElementById('open-add-game').addEventListener('click', () => this.openModal());
        // The small "+" only exists on the Library page
        const smallAdd = document.getElementById('open-add-game-small');
        if (smallAdd) smallAdd.addEventListener('click', () => this.openModal());
        document.getElementById('close-add-game').addEventListener('click', () => this.closeModal());
        document.getElementById('cancel-add-game').addEventListener('click', () => this.closeModal());
        this.backdrop.addEventListener('click', (event) => {
            if (event.target === this.backdrop) this.closeModal(); // click outside the window
        });
        document.addEventListener('keydown', (event) => {
            if (event.key === 'Escape' && this.backdrop.classList.contains('open')) this.closeModal();
        });

        this.form.addEventListener('submit', (event) => {
            event.preventDefault(); // stop the page from reloading
            this.submit();
        });
    }

    // ---- Window ----
    openModal() {
        this.backdrop.classList.add('open');
        this.updateLaunchField();
        this.nameInput.focus();
    }

    closeModal() {
        this.backdrop.classList.remove('open');
        this.form.reset();
        this.updateLaunchField();
    }

    // Shows only the boxes that belong to the chosen platform
    updateLaunchField() {
        const platform = this.platformSelect.value;
        const config = ImportGame.LAUNCH_HINTS[platform];
        this.launchIdInput.placeholder = config.placeholder;
        this.launchIdHint.innerHTML = config.hint;

        const isSteam = platform === 'Steam';
        this.steamAutofillRow.style.display = isSteam ? '' : 'none';
        this.steamImportRow.style.display = isSteam ? '' : 'none';
        if (isSteam) {
            this.maybeAutoLookupSteam();
        } else {
            this.steamUrlInput.value = '';
            ImportGame.setStatus(this.steamAutofillStatus, '');
            ImportGame.setStatus(this.steamLookupStatus, '');
        }

        const isEpic = platform === 'Epic Games';
        this.epicImportRow.style.display = isEpic ? '' : 'none';
        if (isEpic) {
            this.renderEpicSelect();
            this.maybeAutoLookupEpic();
        } else {
            ImportGame.setStatus(this.epicLookupStatus, '');
        }

        const isBattle = platform === 'Battle.net';
        this.battleImportRow.style.display = isBattle ? '' : 'none';
        if (isBattle) this.maybeAutoLookupBattle();
        else ImportGame.setStatus(this.battleLookupStatus, '');
    }

    // Builds the new game from the form and gives it to the app
    submit() {
        const name = this.nameInput.value.trim();
        if (!name) return;

        const platform = this.platformSelect.value;
        const launchId = this.launchIdInput.value.trim();

        if (platform === 'Epic Games' && launchId && launchId.split(':').length !== 3) {
            alert('Epic Launch IDs need three colon-separated parts: namespace:catalogItemId:appName');
            return;
        }

        const game = { title: name, platform: platform, playStyle: this.playStyleSelect.value, launchId: launchId, totalMinutes: 0, lastPlayedAt: null };
        this.closeModal();
        this.onGameImported(game);
    }

    // ================================================================
    // Shared helpers
    // ================================================================

    // Saved lists live in the browser's localStorage
    static loadList(key) {
        try {
            const saved = JSON.parse(localStorage.getItem(key) || '[]');
            return Array.isArray(saved) ? saved : [];
        } catch (e) {
            return [];
        }
    }

    static saveList(key, list) {
        try { localStorage.setItem(key, JSON.stringify(list)); } catch (e) { /* still works this visit */ }
    }

    // Lowercase and strip punctuation, so "Counter-Strike: GO" matches "counter strike go"
    static normalizeName(s) {
        return s.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
    }

    // Number of single-letter changes between two names (used to forgive typos)
    static levenshtein(a, b) {
        const m = a.length, n = b.length;
        const dp = new Array(n + 1);
        for (let j = 0; j <= n; j++) dp[j] = j;
        for (let i = 1; i <= m; i++) {
            let prev = dp[0];
            dp[0] = i;
            for (let j = 1; j <= n; j++) {
                const temp = dp[j];
                dp[j] = Math.min(dp[j] + 1, dp[j - 1] + 1, prev + (a[i - 1] === b[j - 1] ? 0 : 1));
                prev = temp;
            }
        }
        return dp[n];
    }

    // Finds a game in a [[id, name], ...] list: exact name, then a name
    // that contains what you typed, then the closest typo match.
    static findListMatch(list, query) {
        const q = ImportGame.normalizeName(query);
        if (q.length < 3 || !list.length) return null;
        const norms = list.map(g => ImportGame.normalizeName(g[1]));
        let i = norms.indexOf(q);
        if (i === -1) i = norms.findIndex(n => n.indexOf(q) !== -1);
        if (i !== -1) return { id: list[i][0], name: list[i][1] };
        let best = null, bestDist = Infinity;
        for (let j = 0; j < norms.length; j++) {
            const dist = ImportGame.levenshtein(q, norms[j]);
            if (dist <= Math.max(2, Math.floor(norms[j].length * 0.25)) && dist < bestDist) {
                bestDist = dist;
                best = { id: list[j][0], name: list[j][1] };
            }
        }
        return best;
    }

    // Fills an installed-games drop-down from a list
    static fillSelect(sel, list, emptyText, clearButtonId) {
        sel.innerHTML = '';
        const first = document.createElement('option');
        first.value = '';
        first.textContent = list.length ? 'Pick an installed game…' : emptyText;
        sel.appendChild(first);
        list.forEach((g, i) => {
            const opt = document.createElement('option');
            opt.value = String(i);
            opt.textContent = g[1];
            sel.appendChild(opt);
        });
        sel.disabled = !list.length;
        document.getElementById(clearButtonId).style.display = list.length ? '' : 'none';
    }

    // ================================================================
    // Steam
    // ================================================================

    // ---- Name lookup in the big Steam list ----
    buildSteamIndex() {
        if (this.steamNameIndex) return;
        this.steamNameIndex = new Map();
        this.steamNormNames = new Array(STEAM_GAMES.length);
        for (let i = 0; i < STEAM_GAMES.length; i++) {
            const norm = ImportGame.normalizeName(STEAM_GAMES[i][1]);
            this.steamNormNames[i] = norm;
            // Names under 3 letters would match almost anything, so skip them.
            // The first (most popular) game with a name wins.
            if (norm.length >= 3 && !this.steamNameIndex.has(norm)) {
                this.steamNameIndex.set(norm, { id: STEAM_GAMES[i][0], name: STEAM_GAMES[i][1] });
            }
        }
    }

    // True if each typed word is the start of a name word, in the same order
    static wordsStartWords(qWords, nameWords) {
        let j = 0;
        for (const w of qWords) {
            while (j < nameWords.length && !nameWords[j].startsWith(w)) j++;
            if (j === nameWords.length) return false;
            j++;
        }
        return true;
    }

    findSteamMatch(query) {
        this.buildSteamIndex();
        const q = ImportGame.normalizeName(query);
        if (q.length < 3) return null;

        // 1. Exact name
        const exact = this.steamNameIndex.get(q);
        if (exact) return exact;

        // 2. Every word you typed starts a word in the name, in order
        //    (so "sim 4" finds "The Sims 4"; most popular first)
        const qWords = q.split(' ');
        for (let i = 0; i < STEAM_GAMES.length; i++) {
            const norm = this.steamNormNames[i];
            if (norm.length < 3) continue;
            if (ImportGame.wordsStartWords(qWords, norm.split(' '))) {
                return { id: STEAM_GAMES[i][0], name: STEAM_GAMES[i][1] };
            }
        }

        // 3. A name that contains what you typed (most popular first)
        for (let i = 0; i < STEAM_GAMES.length; i++) {
            const norm = this.steamNormNames[i];
            if (norm.length < 3) continue;
            if (norm.indexOf(q) !== -1) {
                return { id: STEAM_GAMES[i][0], name: STEAM_GAMES[i][1] };
            }
        }

        // 4. Closest typo match among names of a similar length
        let best = null, bestDist = Infinity;
        for (let i = 0; i < STEAM_GAMES.length; i++) {
            const norm = this.steamNormNames[i];
            if (norm.length < 3) continue;
            if (Math.abs(norm.length - q.length) > 4) continue;
            const dist = ImportGame.levenshtein(q, norm);
            const threshold = Math.max(2, Math.floor(norm.length * 0.25));
            if (dist <= threshold && dist < bestDist) {
                bestDist = dist;
                best = { id: STEAM_GAMES[i][0], name: STEAM_GAMES[i][1] };
                if (dist === 0) break;
            }
        }
        return best;
    }

    // Runs as you type: installed games first, then the big Steam list.
    // Waits 200ms after the last key so it doesn't search on every keystroke.
    maybeAutoLookupSteam() {
        if (this.platformSelect.value !== 'Steam') return;

        const name = this.nameInput.value.trim();
        clearTimeout(this.steamLookupTimer);
        if (name.length < 3) {
            ImportGame.setStatus(this.steamLookupStatus, '');
            return;
        }

        this.steamLookupTimer = setTimeout(() => {
            const installed = ImportGame.findListMatch(this.steamInstalled, name);
            if (installed) {
                this.launchIdInput.value = installed.id;
                ImportGame.setStatus(this.steamLookupStatus, 'Matched installed game "' + installed.name + '" — Launch ID ' + installed.id + ' filled in.');
                return;
            }
            const match = this.findSteamMatch(name);
            if (match && this.steamInstalled.length) {
                // Your installed list is loaded and this game isn't in it
                this.launchIdInput.value = match.id;
                ImportGame.setStatus(this.steamLookupStatus, 'Matched "' + match.name + '" (Launch ID ' + match.id + '), but it isn\'t in your installed Steam games. ' +
                    'You can still add it — Play will open it in Steam so you can install it.', true);
            } else if (match) {
                // No installed list loaded, so we can't tell if it's installed
                this.launchIdInput.value = match.id;
                ImportGame.setStatus(this.steamLookupStatus, 'Matched "' + match.name + '" — Launch ID ' + match.id + ' filled in. ' +
                    'Load your installed Steam games above to check whether it\'s installed.');
            } else {
                ImportGame.setStatus(this.steamLookupStatus, 'No match in the local Steam list — enter the ID manually or use the fallback below.', true);
            }
        }, 200);
    }

    // ---- Pasted store link or App ID ----
    handleSteamUrlInput() {
        const value = this.steamUrlInput.value.trim();
        const fromLink = value.match(/store\.steampowered\.com\/app\/(\d+)/i);
        const appId = /^\d+$/.test(value) ? value : (fromLink ? fromLink[1] : null);
        if (appId) {
            this.launchIdInput.value = appId;
            ImportGame.setStatus(this.steamAutofillStatus, 'Found App ID ' + appId + ' — filled in above.');
        } else if (value) {
            ImportGame.setStatus(this.steamAutofillStatus, 'Couldn\'t find an App ID in that link — check it\'s a store.steampowered.com/app/ URL.', true);
        } else {
            ImportGame.setStatus(this.steamAutofillStatus, '');
        }
    }

    // ---- Installed Steam games ----
    // Steam keeps steamapps\appmanifest_<appId>.acf for every installed game,
    // with the App ID and name inside.
    static steamEntryFromAcf(text, fileName) {
        const id = (text.match(/"appid"\s+"(\d+)"/i) || [])[1] || (fileName.match(/appmanifest_(\d+)\.acf$/i) || [])[1];
        const name = (text.match(/"name"\s+"((?:[^"\\]|\\.)*)"/i) || [])[1];
        if (!id) return { skip: fileName + ' (no App ID)' };
        if (id === '228980') return { skip: (name || id) + ' (not a game)' }; // Steamworks Common Redistributables
        return { entry: [id, name ? name.replace(/\\(.)/g, '$1') : 'App ' + id] };
    }

    importSteamManifests() {
        const input = this.steamFilesInput;
        const files = Array.from(input.files || []).filter(f => /\.acf$/i.test(f.name));
        input.value = '';
        if (!files.length) {
            ImportGame.setStatus(this.steamImportStatus, 'No appmanifest_*.acf files picked. They are in C:\\Program Files (x86)\\Steam\\steamapps (and each other library\'s steamapps folder).', true);
            return;
        }
        ImportGame.setStatus(this.steamImportStatus, 'Reading ' + files.length + ' file(s)…');
        Promise.all(files.map(f => f.text().then(t => ImportGame.steamEntryFromAcf(t, f.name), () => ({ skip: f.name + ' (unreadable)' }))))
            .then(results => {
                const skipped = results.filter(r => r.skip).map(r => r.skip);
                const skipNote = skipped.length ? ' Skipped: ' + skipped.join(', ') + '.' : '';
                const found = results.filter(r => r.entry);
                if (!found.length) {
                    ImportGame.setStatus(this.steamImportStatus, 'Found no installed games in those files.' + skipNote, true);
                    return;
                }
                // Add to the saved list, so loading a second Steam library adds to the first
                const byId = new Map(this.steamInstalled.map(g => [g[0], g]));
                let added = 0;
                found.forEach(r => { if (!byId.has(r.entry[0])) added++; byId.set(r.entry[0], r.entry); });
                this.steamInstalled = Array.from(byId.values()).sort((a, b) => a[1].localeCompare(b[1]));
                ImportGame.saveList(ImportGame.STEAM_STORAGE_KEY, this.steamInstalled);
                this.renderSteamSelect();
                ImportGame.setStatus(this.steamImportStatus, 'Read ' + found.length + ' game(s), ' + added + ' new. ' +
                    this.steamInstalled.length + ' installed Steam game(s) in the list.' + skipNote);
                this.maybeAutoLookupSteam();
            });
    }

    renderSteamSelect() {
        ImportGame.fillSelect(this.steamGameSelect, this.steamInstalled, 'No Steam games loaded yet', 'steam-clear-button');
    }

    pickSteamGame() {
        const g = this.steamInstalled[Number(this.steamGameSelect.value)];
        if (this.steamGameSelect.value === '' || !g) return;
        clearTimeout(this.steamLookupTimer);
        this.nameInput.value = g[1];
        this.launchIdInput.value = g[0];
        ImportGame.setStatus(this.steamLookupStatus, 'Launch ID ' + g[0] + ' for "' + g[1] + '" filled in.');
    }

    clearSteamInstalled() {
        this.steamInstalled = [];
        ImportGame.saveList(ImportGame.STEAM_STORAGE_KEY, []);
        this.renderSteamSelect();
        ImportGame.setStatus(this.steamImportStatus, 'List cleared. Load your appmanifest files again to rebuild it.');
    }

    // ================================================================
    // Epic Games
    // Epic has no public game list, so IDs come from files the launcher
    // keeps on your PC. A Launch ID is namespace:catalogItemId:appName.
    // ================================================================

    // An .item file from ...\EpicGamesLauncher\Data\Manifests (one per game).
    // Add-ons/DLC are skipped.
    static epicEntryFromManifest(m) {
        if (!m || typeof m !== 'object') return { skip: 'not a manifest' };
        const ns = m.CatalogNamespace, item = m.CatalogItemId, app = m.AppName;
        const name = m.DisplayName || app || '?';
        if (!ns || !item || !app) return { skip: name + ' (missing IDs)' };
        const cats = Array.isArray(m.AppCategories) ? m.AppCategories : [];
        if (cats.indexOf('addons') !== -1 && cats.indexOf('games') === -1) return { skip: name + ' (add-on)' };
        return { entry: [ns + ':' + item + ':' + app, name] };
    }

    // LauncherInstalled.dat lists every installed app (named by install folder)
    static epicEntriesFromInstalledList(data) {
        return (data.InstallationList || []).map(x => {
            if (!x.NamespaceId || !x.ItemId || !x.AppName) return { skip: (x.AppName || '?') + ' (missing IDs)' };
            const folder = String(x.InstallLocation || '').split(/[\\/]/).filter(Boolean).pop();
            return { entry: [x.NamespaceId + ':' + x.ItemId + ':' + x.AppName, folder || x.AppName] };
        });
    }

    // <game folder>\.egstore\*.mancpn - found when you load e.g. D:\Epic Games.
    // It has the IDs but no name, so the game's folder name is used.
    static epicEntryFromMancpn(m, file) {
        if (!m || !m.CatalogNamespace || !m.CatalogItemId || !m.AppName) return { skip: file.name + ' (missing IDs)' };
        const parts = String(file.webkitRelativePath || '').split('/');
        const eg = parts.indexOf('.egstore');
        const folder = eg > 0 ? parts[eg - 1] : '';
        return { entry: [m.CatalogNamespace + ':' + m.CatalogItemId + ':' + m.AppName, folder || m.AppName] };
    }

    // Reads every Epic file in the picked folder and replaces the saved list
    importEpicManifests(input) {
        const files = Array.from(input.files || []).filter(f => /\.(item|dat|mancpn)$/i.test(f.name));
        input.value = '';
        if (!files.length) {
            ImportGame.setStatus(this.epicImportStatus, 'No .item files found there. Pick the Manifests folder: C:\\ProgramData\\Epic\\EpicGamesLauncher\\Data\\Manifests', true);
            return;
        }
        ImportGame.setStatus(this.epicImportStatus, 'Reading ' + files.length + ' file(s)…');
        Promise.all(files.map(f => f.text().then(t => {
            let data;
            try { data = JSON.parse(t.replace(/^\uFEFF/, '')); } catch (e) { return [{ skip: f.name + ' (unreadable)' }]; }
            if (data && Array.isArray(data.InstallationList)) return ImportGame.epicEntriesFromInstalledList(data);
            if (/\.mancpn$/i.test(f.name)) return [ImportGame.epicEntryFromMancpn(data, f)];
            return [ImportGame.epicEntryFromManifest(data)];
        }, () => [{ skip: f.name + ' (unreadable)' }]))).then(results => {
            this.applyEpicResults([].concat.apply([], results), 'Loaded ' + files.length + ' file(s)');
        });
    }

    // Saves the games that were found and reports what was found/skipped.
    // If the same game appears twice, a proper name beats a folder name.
    applyEpicResults(all, label) {
        const skipped = all.filter(r => r.skip).map(r => r.skip);
        const byId = new Map();
        all.forEach(r => {
            if (!r.entry) return;
            const prev = byId.get(r.entry[0]);
            if (!prev || prev[1] === prev[0].split(':')[2]) byId.set(r.entry[0], r.entry);
        });
        const list = Array.from(byId.values()).sort((a, b) => a[1].localeCompare(b[1]));
        const skipNote = skipped.length ? ' Skipped: ' + skipped.join(', ') + '.' : '';
        if (!list.length) {
            ImportGame.setStatus(this.epicImportStatus, label + ': found no installed games.' + skipNote, true);
            return;
        }
        this.epicGames = list;
        ImportGame.saveList(ImportGame.EPIC_STORAGE_KEY, list);
        this.renderEpicSelect();
        ImportGame.setStatus(this.epicImportStatus, label + ': found ' + list.length + ' game(s): ' + list.map(g => g[1]).join(', ') + '.' + skipNote);
        this.maybeAutoLookupEpic();
    }

    renderEpicSelect() {
        ImportGame.fillSelect(this.epicGameSelect, this.epicGames, 'No Epic games loaded yet', 'epic-clear-button');
    }

    clearEpicGames() {
        this.epicGames = [];
        ImportGame.saveList(ImportGame.EPIC_STORAGE_KEY, []);
        this.renderEpicSelect();
        ImportGame.setStatus(this.epicImportStatus, 'List cleared. Load your Epic files again to rebuild it.');
    }

    pickEpicGame() {
        const g = this.epicGames[Number(this.epicGameSelect.value)];
        if (this.epicGameSelect.value === '' || !g) return;
        this.nameInput.value = g[1];
        this.launchIdInput.value = g[0];
        ImportGame.setStatus(this.epicLookupStatus, 'Launch ID for "' + g[1] + '" filled in.');
    }

    // Runs as you type: looks for the name in your installed Epic games
    maybeAutoLookupEpic() {
        if (this.platformSelect.value !== 'Epic Games') return;

        const name = this.nameInput.value.trim();
        clearTimeout(this.epicLookupTimer);
        if (name.length < 3) {
            ImportGame.setStatus(this.epicLookupStatus, '');
            return;
        }
        if (!this.epicGames.length) {
            ImportGame.setStatus(this.epicLookupStatus, 'Load your installed Epic games above to fill this in automatically.');
            return;
        }

        this.epicLookupTimer = setTimeout(() => {
            const match = ImportGame.findListMatch(this.epicGames, name);
            if (match) {
                this.launchIdInput.value = match.id;
                ImportGame.setStatus(this.epicLookupStatus, 'Matched "' + match.name + '" — Launch ID filled in.');
            } else {
                ImportGame.setStatus(this.epicLookupStatus, 'Not in your installed Epic games. You can still add it — Play will open it in the Epic Games Launcher so you can install it.', true);
            }
        }, 200);
    }

    // ================================================================
    // Battle.net
    // Games open with battlenet://<product code>, e.g. battlenet://Pro.
    // The catalog is small, so every known game is listed here as
    // [code, name, uid]. The uid is the game's name inside product.db.
    // ================================================================
    static BATTLENET_GAMES = [
        ['WoW',  'World of Warcraft', 'wow'],
        ['Pro',  'Overwatch 2', 'prometheus'],
        ['Fen',  'Diablo IV', 'fenris'],
        ['D3',   'Diablo III', 'diablo3'],
        ['OSI',  'Diablo II: Resurrected', 'osi'],
        ['ANBS', 'Diablo Immortal', 'anbs'],
        ['WTCG', 'Hearthstone', 'hs_beta'],
        ['Hero', 'Heroes of the Storm', 'heroes'],
        ['S2',   'StarCraft II', 's2'],
        ['S1',   'StarCraft: Remastered', 's1'],
        ['W3',   'Warcraft III: Reforged', 'w3'],
        ['RTRO', 'Blizzard Arcade Collection', 'rtro'],
        ['AUKS', 'Call of Duty', 'auks'],
        ['ODIN', 'Call of Duty: Modern Warfare (2019)', 'odin'],
        ['LAZR', 'Call of Duty: Modern Warfare 2 Campaign Remastered', 'lazarus'],
        ['ZEUS', 'Call of Duty: Black Ops Cold War', 'zeus'],
        ['FORE', 'Call of Duty: Vanguard', 'fore'],
        ['VIPR', 'Call of Duty: Black Ops 4', 'viper'],
        ['WLBY', 'Crash Bandicoot 4: It\'s About Time', 'wlby']
    ];

    // product.db is a binary file, but each installed game's uid is stored
    // as one byte giving its length followed by the uid itself, so we
    // search for exactly that for every known game.
    static battlenetFromProductDb(bytes) {
        const found = [];
        ImportGame.BATTLENET_GAMES.forEach(g => {
            const uid = g[2];
            const n = uid.length;
            for (let i = 0; i + n < bytes.length; i++) {
                if (bytes[i] !== n) continue;
                let ok = true;
                for (let k = 0; k < n; k++) {
                    if (bytes[i + 1 + k] !== uid.charCodeAt(k)) { ok = false; break; }
                }
                if (ok) { found.push([g[0], g[1]]); break; }
            }
        });
        return found;
    }

    importBattlenetDb() {
        const input = this.battleFilesInput;
        const file = Array.from(input.files || []).find(f => /\.db$/i.test(f.name));
        input.value = '';
        if (!file) {
            ImportGame.setStatus(this.battleImportStatus, 'Pick product.db from C:\\ProgramData\\Battle.net\\Agent');
            return;
        }
        file.arrayBuffer().then(buf => {
            const list = ImportGame.battlenetFromProductDb(new Uint8Array(buf));
            if (!list.length) {
                ImportGame.setStatus(this.battleImportStatus, 'Found no installed Battle.net games in ' + file.name + '.', true);
                return;
            }
            this.battleInstalled = list.sort((a, b) => a[1].localeCompare(b[1]));
            ImportGame.saveList(ImportGame.BATTLENET_STORAGE_KEY, this.battleInstalled);
            this.renderBattleSelect();
            ImportGame.setStatus(this.battleImportStatus, 'Found ' + list.length + ' game(s): ' + list.map(g => g[1]).join(', ') + '.');
            this.maybeAutoLookupBattle();
        }, () => {
            ImportGame.setStatus(this.battleImportStatus, 'Couldn\'t read ' + file.name + '.', true);
        });
    }

    renderBattleSelect() {
        ImportGame.fillSelect(this.battleGameSelect, this.battleInstalled, 'No Battle.net games loaded yet', 'battle-clear-button');
    }

    pickBattleGame() {
        const g = this.battleInstalled[Number(this.battleGameSelect.value)];
        if (this.battleGameSelect.value === '' || !g) return;
        clearTimeout(this.battleLookupTimer);
        this.nameInput.value = g[1];
        this.launchIdInput.value = g[0];
        ImportGame.setStatus(this.battleLookupStatus, 'Launch ID ' + g[0] + ' for "' + g[1] + '" filled in.');
    }

    clearBattleInstalled() {
        this.battleInstalled = [];
        ImportGame.saveList(ImportGame.BATTLENET_STORAGE_KEY, []);
        this.renderBattleSelect();
        ImportGame.setStatus(this.battleImportStatus, 'List cleared. Load product.db again to rebuild it.');
    }

    // Runs as you type: installed games first, then every known Battle.net
    // game, so uninstalled games still get a code.
    maybeAutoLookupBattle() {
        if (this.platformSelect.value !== 'Battle.net') return;
        const name = this.nameInput.value.trim();
        clearTimeout(this.battleLookupTimer);
        if (name.length < 2) { ImportGame.setStatus(this.battleLookupStatus, ''); return; }
        this.battleLookupTimer = setTimeout(() => {
            const installed = ImportGame.findListMatch(this.battleInstalled, name);
            const known = installed || ImportGame.findListMatch(ImportGame.BATTLENET_GAMES.map(g => [g[0], g[1]]), name);
            if (known) {
                this.launchIdInput.value = known.id;
                ImportGame.setStatus(this.battleLookupStatus, (installed ? 'Matched installed game "' : 'Matched "') + known.name + '" — Launch ID ' + known.id + ' filled in.' +
                    (installed ? '' : ' If it isn\'t installed, Play opens it in Battle.net so you can install it.'));
            } else {
                ImportGame.setStatus(this.battleLookupStatus, 'Not a known Battle.net game — enter its product code by hand if you know it.', true);
            }
        }, 200);
    }
}